<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('service.edit');verify_csrf();$uid=(int)$_POST['unit_id'];$u=$pdo->prepare('SELECT current_meter FROM units WHERE id=?');$u->execute([$uid]);$current=(float)$u->fetchColumn();$status=service_status($current,(float)$_POST['next_service_meter'],$_POST['next_service_date']);$old=$pdo->prepare('SELECT status FROM service_schedules WHERE unit_id=?');$old->execute([$uid]);$oldStatus=$old->fetchColumn()?:null;$stmt=$pdo->prepare('INSERT INTO service_schedules(unit_id,service_interval,next_service_meter,next_service_date,status,notes) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE service_interval=VALUES(service_interval),next_service_meter=VALUES(next_service_meter),next_service_date=VALUES(next_service_date),status=VALUES(status),notes=VALUES(notes)');$stmt->execute([$uid,(float)$_POST['service_interval'],(float)$_POST['next_service_meter'],$_POST['next_service_date'],$status,trim($_POST['notes']??'')]);add_history($pdo,'service_schedule',$uid,$oldStatus,$status,'Jadwal service diperbarui');audit($pdo,'UPDATE','service_schedule',$uid,'Status '.$status);flash('success','Jadwal service disimpan dengan status otomatis '.$status.'.');redirect('../'.page_url('maintenance'));
